/**
 * Policy issuance (4B-5) — photographed and measured at 1360, 1440 and 390.
 *
 * Every state the issuance Space passes through, from ready to applied, plus the refusals: a
 * person who may not approve, an out-of-date check, a period that was not read. Some states are
 * reached by clicking, exactly as a person would — the apply preview is generated by the server
 * (stubbed here) only after the person chooses a target and a premium basis — and the evidence
 * highlight is revealed on the row it belongs to. The harness serves each from its URL, so the run
 * needs no database and invents no brokerage: every name is an obvious placeholder.
 *
 *   node scripts/visual/capture-issuance.mjs
 */
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { chromium } from "playwright";
import { VIEWPORTS } from "./capture.mjs";

function browserPath() {
  for (const p of ["/opt/pw-browsers/chromium-1194/chrome-linux/chrome", "/opt/pw-browsers/chromium/chrome-linux/chrome"]) {
    if (existsSync(p)) return p;
  }
  return undefined;
}

const HARNESS = process.env.HARNESS ?? "http://127.0.0.1:5199/parity/shell-harness/";
const AT = "/placements/40000000-0000-4000-8000-00000000000a/issuance";
const url = (stage, extra = "") => `${HARNESS}?at=${AT}&stage=${stage}${extra}`;

/** Open the apply form, choose a target and a basis, and ask the server for its preview. */
const preview = (target, basis) => async (page) => {
  await page.getByRole("button", { name: "Preview writing it to the policy record" }).click();
  await page.getByRole("radio", { name: target }).check();
  if (basis) await page.getByRole("radio", { name: basis }).check();
  await page.getByRole("button", { name: "Preview the change" }).click();
  await page.waitForTimeout(600);
  await page.getByText(/^What applying will do/i).first().evaluate((el) => el.scrollIntoView({ block: "start" })).catch(() => {});
};

const STATES = [
  { name: "issuance-not-ready", url: url("not-ready") },
  { name: "issuance-ready", url: url("ready") },
  { name: "issuance-draft-approval-required", url: url("draft") },
  { name: "issuance-approval-refused", url: url("draft", "&perms=officer") },
  { name: "issuance-approval-superseded", url: url("superseded") },
  { name: "issuance-approved-not-sent", url: url("approved") },
  {
    name: "issuance-record-sent-form", url: url("approved"),
    act: async (page) => { await page.getByRole("button", { name: "Record that it was sent" }).first().click(); await page.waitForTimeout(300); },
  },
  { name: "issuance-with-insurer", url: url("with-insurer") },
  { name: "issuance-document-received", url: url("received") },
  { name: "issuance-ready-for-check", url: url("reviewed") },
  { name: "issuance-check-stale", url: url("stale") },
  { name: "issuance-conflict", url: url("conflict") },
  {
    name: "issuance-resolution-form", url: url("conflict"),
    act: async (page) => { await page.getByRole("button", { name: "Resolve" }).first().click(); await page.waitForTimeout(300); },
  },
  { name: "issuance-resolved", url: url("resolved") },
  { name: "issuance-apply-preview", url: url("ready-to-apply"), act: preview("Create a new policy", "The gross premium") },
  { name: "issuance-apply-preview-update", url: url("ready-to-apply"), act: preview(/^Update PH\/MTR\/OLD/, "The total payable") },
  /* Someone who may not approve sees the action, disabled, with the reason — never hidden. */
  { name: "issuance-apply-permission-refused", url: url("ready-to-apply", "&perms=officer") },
  { name: "issuance-missing-info", url: url("missing-info"), act: preview("Create a new policy", "The gross premium") },
  { name: "issuance-ask-prepared-apply", url: url("prepared-apply") },
  { name: "issuance-applied-receipt", url: url("applied") },
  {
    name: "issuance-evidence-highlight", url: url("conflict"),
    act: async (page) => { await page.getByRole("button", { name: "Show where" }).first().click(); await page.waitForTimeout(300); },
  },
];

const outDir = resolve(".local-visual/shots/issuance");
mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch({ executablePath: browserPath() });
const report = { viewports: {} };
try {
  for (const vp of VIEWPORTS) {
    report.viewports[vp.name] = {};
    for (const state of STATES) {
      const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
      const consoleErrors = [];
      page.on("console", (m) => { if (m.type() === "error") consoleErrors.push(`${m.text().slice(0, 160)} @ ${m.location().url ?? ""}`.slice(0, 240)); });
      page.on("requestfailed", (r) => consoleErrors.push(`request failed: ${r.url().slice(0, 200)}`));
      page.on("response", (r) => { if (r.status() >= 400) consoleErrors.push(`${r.status()}: ${r.url().slice(0, 200)}`); });
      page.on("pageerror", (e) => consoleErrors.push(`pageerror: ${e.message.slice(0, 200)}`));
      await page.goto(state.url, { waitUntil: "load" });
      await page.waitForTimeout(2200);
      let actError = null;
      if (state.act) await state.act(page).catch((e) => { actError = String(e.message ?? e).slice(0, 200); });

      const measured = await page.evaluate(() => {
        const tables = [...document.querySelectorAll(".sp-space table")].map((t) => ({ w: t.scrollWidth, box: t.parentElement?.clientWidth ?? 0, display: getComputedStyle(t).display }));
        return {
          title: document.querySelector(".sp-title")?.textContent ?? null,
          blockLabels: [...document.querySelectorAll(".sp-block-label")].map((n) => n.textContent),
          text: (document.body.textContent ?? "").trim().length,
          body: document.body.innerText,
          tables,
          overflow: { scrollWidth: document.documentElement.scrollWidth, clientWidth: document.documentElement.clientWidth },
        };
      });
      const { body, ...kept } = measured;
      report.viewports[vp.name][state.name] = { ...kept, consoleErrors, actError, vocabulary: vocabularyProblems(body, state.name) };
      await page.screenshot({ path: `${outDir}/${state.name}--${vp.name}.png`, fullPage: true });
      await page.close();
    }
    console.log(`${vp.name}: ${STATES.length} state(s)`);
  }
} finally {
  await browser.close();
}
writeFileSync(`${outDir}/geometry.json`, JSON.stringify(report, null, 2));

/** Words that would let one step pass for the next, or that the product has retired. */
function vocabularyProblems(text, name) {
  const out = [];
  if (/\bNeeds you\b/.test(text)) out.push('"Needs you" on screen');
  if (/(^|\n|\s)Waiting(\s*$|\n)/m.test(text)) out.push('a bare "Waiting"');
  if (/\bSpace\b/.test(text.replace(/Placeholder Company/g, ""))) out.push('"Space" on screen');
  if (!name.includes("applied") && /\b(policy (was|has been) issued|issued the policy)\b/i.test(text)) out.push('says the policy was issued before it was applied');
  return out;
}

const problems = [];
for (const [vp, states] of Object.entries(report.viewports)) {
  for (const [name, r] of Object.entries(states)) {
    if (r.text < 200) problems.push(`${vp}/${name}: the screen is empty`);
    if (r.overflow.scrollWidth > r.overflow.clientWidth + 1) problems.push(`${vp}/${name}: horizontal overflow (${r.overflow.scrollWidth} > ${r.overflow.clientWidth})`);
    if (r.consoleErrors.length > 0) problems.push(`${vp}/${name}: ${r.consoleErrors[0]}`);
    if (r.actError) problems.push(`${vp}/${name}: could not reach the state — ${r.actError}`);
    for (const v of r.vocabulary) problems.push(`${vp}/${name}: ${v}`);
    if (/issuance space|placement space/i.test(r.title ?? "")) problems.push(`${vp}/${name}: the title says "${r.title}"`);
  }
}
console.log(`\ngeometry -> ${outDir}/geometry.json`);
if (problems.length > 0) {
  console.error(`\n${problems.length} problem(s):`);
  for (const p of problems) console.error(`  ${p}`);
  process.exit(1);
}
console.log("no empty screens, no horizontal overflow, no console errors, no retired or premature words");
